"""Public business assessment and buyer worksheet. Answers remain in the page only."""
import json, html
from pathlib import Path
from directory_brand import brand_page
ROOT=Path(__file__).resolve().parent
STYLE='''body{font:16px/1.6 system-ui;color:#252525;background:#faf9f6;margin:0}main{max-width:950px;margin:auto;padding:24px}a{color:#a90000}h1{line-height:1.15}section,article{background:white;border:1px solid #ccc;padding:20px;margin:18px 0;break-inside:avoid}label{display:block;margin:10px 0}input,select,button{font:inherit;padding:8px;max-width:100%;box-sizing:border-box}input{border:1px solid #888}textarea{width:100%;min-height:70px}button{cursor:pointer}table{width:100%;border-collapse:collapse}td,th{border:1px solid #aaa;padding:8px;text-align:left}.muted{color:#555;font-size:.9rem}.actions{display:flex;flex-wrap:wrap;gap:12px}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #ba0c2f}@media print{body{background:white}main{padding:0}.actions,.vhg-brand,.knowledge-links{display:none}input,textarea,select{border:1px solid #aaa}section{padding:12px;margin:12px 0}}'''
def shell(title,body,js=''):
 return brand_page('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+STYLE+'__VHG_CSS__</style></head><body><main>__VHG_BRAND__<a href="index.html">Directory home</a><h1>'+title+'</h1>'+body+'</main><script>'+js+'</script></body></html>')
def main():
 data=json.loads((ROOT/'data/business-assessment.json').read_text());cards=[]
 for q in data['questions']:
  cards.append('<article><h2>'+html.escape(q['id']+' · '+q['domain'])+'</h2><p>'+html.escape(q['question'])+'</p><p class="muted">Evidence: '+html.escape(q['evidence'])+' · Weight '+str(q['weight'])+'</p><label>Score <select data-id="'+q['id']+'" data-weight="'+str(q['weight'])+'"><option value="">Not assessed</option>'+''.join('<option value="'+str(n)+'">'+str(n)+' - '+s+'</option>' for n,s in enumerate(['Absent / unknown','Informal / partial','Documented','Implemented and evidenced']))+'</select></label><label>Evidence / owner / next action<textarea data-note="'+q['id']+'"></textarea></label></article>')
 body='''<p>Travis Vought's 33-question diagnostic for Ohio cannabis businesses preparing for banking, financing or internal review.</p><p>Imported from your v2 workbook, dated August 27, 2026. Its regulatory references have not been revalidated for this October edition. This measures documented operational readiness; it does not certify compliance or guarantee bank acceptance.</p><p>Score what you can demonstrate today. Start with weight-3 questions scored zero, then other zero scores and critical partial controls. Answers stay in this page's memory and disappear on reload; export before leaving. No answers or notes are sent to analytics.</p><p><a href="data/business-assessment.json">Download blank question set</a></p><div class="actions"><button id="export" data-track="assessment-export">Export my answers</button><button id="print" data-track="assessment-print">Print my assessment</button></div><section><h2>Your progress</h2><p id="score" aria-live="polite">Not assessed.</p><p id="domains"></p></section><form id="assessment-form">'''+''.join(cards)+'</form><p>After the assessment, use the <a href="index.html?category=Banking+%26+Financial+Services">banking directory</a>, <a href="index.html?category=Accounting+%26+Tax">accounting directory</a> or <a href="index.html?category=Legal+%26+Licensing">legal directory</a> to find support.</p>'
 js='''const qs='''+json.dumps(data['questions']).replace('<','\\u003c')+''';const fields=[...document.querySelectorAll('select[data-weight]')];function calculate(){const answered=fields.filter(e=>e.value!=='');const weight=answered.reduce((s,e)=>s+Number(e.dataset.weight),0);const points=answered.reduce((s,e)=>s+Number(e.value)/3*Number(e.dataset.weight),0);const pct=weight?100*points/weight:null;const critical=answered.filter(e=>e.dataset.weight==='3'&&e.value==='0').length;document.getElementById('score').textContent=answered.length+'/'+fields.length+' assessed. '+(pct===null?'No score yet.':(answered.length<fields.length?'Partial score (answered items only): ':'Overall readiness: ')+pct.toFixed(1)+'%. ')+(answered.length===fields.length?(pct>=80?'GREEN - Strong readiness. ':pct>=60?'YELLOW - Improvement needed. ':'RED - Material gaps. '):'Finish all questions before using an overall rating. ')+critical+' critical zero-score gaps.';document.getElementById('domains').textContent=[...new Set(qs.map(q=>q.domain))].map(d=>{const group=qs.filter(q=>q.domain===d),ans=group.map(q=>fields.find(f=>f.dataset.id===q.id)).filter(f=>f.value!=='');return d+': '+ans.length+'/'+group.length+' assessed';}).join(' · ');}fields.forEach(e=>e.addEventListener('change',calculate));document.getElementById('print').onclick=()=>window.print();document.getElementById('export').onclick=()=>{const rows=qs.map(q=>({...q,score:fields.find(e=>e.dataset.id===q.id).value,notes:document.querySelector('[data-note="'+q.id+'"]').value}));const u=URL.createObjectURL(new Blob([JSON.stringify({assessment:rows},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='my-business-assessment.json';a.click();URL.revokeObjectURL(u);};calculate();'''
 (ROOT/'assessment.html').write_text(shell('Business financial access & compliance self-assessment',body,js))
 body='''<p>A first-visit guide and shopping worksheet. Start with your goal and experience, then discuss product, strength and budget with dispensary staff. Your answers stay on this page and are not saved or sent.</p><div class="actions"><a href="assets/dispensary-shopping-guide.pdf">Download printable guide (PDF)</a><button id="print" data-track="buyer-guide-print">Print my worksheet</button></div><section><h2>What are you trying to accomplish?</h2><label>My goal / what I want to ask about <input style="width:100%" placeholder="Relaxation, product education, avoiding smoke, or a concern to discuss with a clinician"></label><label>Experience <select><option>First time</option><option>Occasional</option><option>Returning after a break</option><option>Experienced, new product form</option></select></label><label>Budget including tax / fees $ <input type="number" min="0"></label><label>Product <select><option>Gummies / edibles</option><option>Flower / pre-rolls</option><option>Concentrates / cartridges</option><option>Tincture / oral oil</option><option>Topicals</option><option>Not sure</option></select></label><label>Preferences / ingredients to avoid <input style="width:100%"></label></section><section><h2>How long will my purchase last?</h2><p>Use the same unit for package quantity and amount per use: pieces for gummies, mL for oil, grams for flower or concentrate. These are shopping estimates, not dose recommendations. Leave blank if you do not yet know your amount.</p><label>Quantity in one package <input id="quantity" type="number" min="0" step="any"></label><label>Unit <select id="unit"><option>pieces</option><option>mL</option><option>grams</option></select></label><label>Planned amount per use <input id="amount" type="number" min="0" step="any"></label><label>Planned uses per week <input id="frequency" type="number" min="0" step="any"></label><label>Weeks I want covered <input id="weeks" type="number" min="0" step="any"></label><p id="estimate" aria-live="polite">Enter your own estimates to calculate supply duration.</p><p>Example: 10 gummies, one-quarter gummy per use, twice per week = 40 uses or 20 weeks. This says nothing about the appropriate THC amount. Check mg THC per gummy and whether it can be portioned reliably. Buy a small trial amount first when your response is unknown.</p></section><section><h2>Ask before buying</h2><ul><li>How much THC and CBD are in one serving and the whole package?</li><li>How is this used, and when do effects begin, peak and wear off?</li><li>Can it be measured or divided reliably? What device is required?</li><li>What is the final cost with taxes, fees and any device?</li><li>Are there allergens, added ingredients or a batch testing report?</li><li>How should I store it securely, and what is the expiration date?</li></ul><p>For new or occasional edible users, Health Canada gives a starting reference of 2.5 mg THC or less and advises allowing up to four hours for full effects before taking more. Higher-potency extracts can be difficult for beginners to measure. Oral oils used under the tongue and swallowed oils can behave differently. Ask a clinician or pharmacist about medicines and health concerns.</p><p>Do not drive while impaired. Keep products locked away from children and pets. Avoid combining with alcohol. Strain names do not guarantee effects.</p><p>For Ohio adult-use purchases, bring current government-issued photo ID showing you are 21 or older. Medical purchasers should bring their active registry card and linked ID and have an active recommendation. Confirm store payment options and hours before travel.</p><p><a href="https://www.canada.ca/en/health-canada/services/drugs-medication/cannabis/resources/lower-your-risks.html">Health Canada: lower-risk starting guidance</a> · <a href="https://codes.ohio.gov/ohio-administrative-code/rule-1301:18-8-08">Ohio adult-use dispensing rule</a> · <a href="knowledge.html">Product forms and labels</a></p></section>'''
 js='''const inputs=['quantity','amount','frequency','weeks'];function calc(){const [q,a,f,w]=inputs.map(id=>Number(document.getElementById(id).value));const o=document.getElementById('estimate');if(!(q>0&&a>0&&f>0)){o.textContent='Enter positive package quantity, amount per use and uses per week.';return;}const uses=q/a;const weeks=uses/f;o.textContent='One package: about '+uses.toFixed(1)+' uses, lasting '+weeks.toFixed(1)+' weeks ('+(weeks*7).toFixed(0)+' days).'+(w>0?' To cover '+w+' weeks: '+(a*f*w).toFixed(2)+' '+document.getElementById('unit').value+'; '+Math.ceil(a*f*w/q)+' whole packages.':'')+' Actual use, waste and shelf life may differ.';}inputs.forEach(id=>document.getElementById(id).addEventListener('input',calc));document.getElementById('unit').addEventListener('change',calc);document.getElementById('print').onclick=()=>window.print();'''
 (ROOT/'buyer-guide.html').write_text(shell('Your dispensary shopping plan',body,js))
if __name__=='__main__':main()
